UPDATE question_content_revision r JOIN teaching_question_proposal p ON p.revision_key=r.revision_key JOIN (question q LEFT JOIN question_legal_subject s ON s.question_id=q.id) ON q.id=p.id SET r.applied_at=COALESCE(r.applied_at,NOW()) WHERE r.question_id=p.id AND BINARY CAST(r.before_content AS CHAR)=BINARY CAST(p.before_content AS CHAR) AND BINARY CAST(r.after_content AS CHAR)=BINARY CAST(p.after_content AS CHAR) AND BINARY CAST(r.evidence_urls AS CHAR)=BINARY CAST(p.evidence_urls AS CHAR) AND BINARY CAST(CASE WHEN q.type IN ('SINGLE','MULTIPLE') AND JSON_VALID(q.answer) THEN CASE WHEN JSON_TYPE(JSON_EXTRACT(q.answer,'$'))='ARRAY' THEN JSON_SET(JSON_OBJECT('type',q.type,'stem',q.stem,'options',q.options,'answer',q.answer,'analysis',q.analysis,'category',q.category,'discipline',COALESCE(s.discipline,CASE TRIM(q.category) WHEN '刑法' THEN '刑法' WHEN '民法' THEN '民商法' WHEN '行政法' THEN '宪法与行政法' ELSE '综合与待判定' END),'subject',COALESCE(s.subject,CASE TRIM(q.category) WHEN '刑法' THEN '刑法学' WHEN '民法' THEN '民法学' WHEN '行政法' THEN '行政法学' ELSE '待判定' END)),'$.answer',JSON_EXTRACT(q.answer,'$')) ELSE JSON_OBJECT('type',q.type,'stem',q.stem,'options',q.options,'answer',q.answer,'analysis',q.analysis,'category',q.category,'discipline',COALESCE(s.discipline,CASE TRIM(q.category) WHEN '刑法' THEN '刑法' WHEN '民法' THEN '民商法' WHEN '行政法' THEN '宪法与行政法' ELSE '综合与待判定' END),'subject',COALESCE(s.subject,CASE TRIM(q.category) WHEN '刑法' THEN '刑法学' WHEN '民法' THEN '民法学' WHEN '行政法' THEN '行政法学' ELSE '待判定' END)) END ELSE JSON_OBJECT('type',q.type,'stem',q.stem,'options',q.options,'answer',q.answer,'analysis',q.analysis,'category',q.category,'discipline',COALESCE(s.discipline,CASE TRIM(q.category) WHEN '刑法' THEN '刑法' WHEN '民法' THEN '民商法' WHEN '行政法' THEN '宪法与行政法' ELSE '综合与待判定' END),'subject',COALESCE(s.subject,CASE TRIM(q.category) WHEN '刑法' THEN '刑法学' WHEN '民法' THEN '民法学' WHEN '行政法' THEN '行政法学' ELSE '待判定' END)) END AS CHAR)=BINARY CAST(CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(p.after_content,'$.type')) IN ('SINGLE',