p.after_content,'$.answer'))='STRING' AND JSON_VALID(JSON_UNQUOTE(JSON_EXTRACT(p.after_content,'$.answer'))) AND JSON_TYPE(JSON_EXTRACT(JSON_UNQUOTE(JSON_EXTRACT(p.after_content,'$.answer')),'$'))='ARRAY' THEN JSON_SET(p.after_content,'$.answer',JSON_EXTRACT(JSON_UNQUOTE(JSON_EXTRACT(p.after_content,'$.answer')),'$')) ELSE p.after_content END AS CHAR) AND r.applied_at IS NOT NULL THEN 'APPLIED_OR_ALREADY_APPLIED' ELSE 'BASELINE_CHANGED' END) FROM teaching_question_proposal p LEFT JOIN question q ON q.id=p.id LEFT JOIN question_legal_subject s ON s.question_id=q.id LEFT JOIN question_content_revision r ON r.revision_key=p.revision_key ORDER BY p.id;
